                labelPlacement="floating"
                type="number"
                name="costUSD"
                value={formState.costUSD}
                onIonInput={handleNumberInputChange}
                required
              />
              <IonInput
                fill="outline"
                label="Nombre del Modelo *"
                labelPlacement="floating"
                name="modelName"
                value={formState.modelName}
                onIonInput={handleInputChange}
                required
              />
              <IonDatetime
                label="Marca de Tiempo *"
                labelPlacement="floating"
                presentation="date-time"
                value={formState.timestamp}
                onIonChange={handleDateTimeChange}
                className="custom-datetime"
              />
            </div>
            <IonButton expand="block" onClick={handleSave} disabled={loading}>
              {loading ? <IonSpinner name="dots" /> : (isEditing ? 'Actualizar' : 'Guardar')}
            </IonButton>
            <IonButton expand="block" fill="outline" onClick={() => setShowModal(false)} className="ion-margin-top">
              Cancelar
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar el uso de ejecución de fábrica con referencia "${usageToDelete?.factoryRunRef}"?`}
          buttons=[
            { text: 'Cancelar', role: 'cancel', handler: () => setShowDeleteAlert(false) },
            { text: 'Eliminar', handler: confirmDelete }
          ]
        />
      </IonContent>
    </IonPage>
  );
};

export default FactoryRunUsagePage;
